const PUBLIC_ID_KEY="adder-public-client-v1";
function publicClientId(){
  let id="";
  try{id=localStorage.getItem(PUBLIC_ID_KEY)||""}catch{}
  if(!/^[a-z0-9-]{8,64}$/.test(id)){
    const raw=globalThis.crypto?.randomUUID?.()||`p-${Math.random().toString(36).slice(2)}-${Math.random().toString(36).slice(2)}`;
    id=String(raw).toLowerCase().replace(/[^a-z0-9-]/g,"").slice(0,56);
    try{localStorage.setItem(PUBLIC_ID_KEY,id)}catch{}
  }
  return id;
}
