function modelArt(gender,color){const skin="#d8aa91",hair="#252522",wide=gender==="female"?17:20;return `<svg class="model-art" viewBox="0 0 100 210" aria-label="${gender==="female"?"한국인 여성":"한국인 남성"} 모델"><ellipse cx="50" cy="23" rx="15" ry="18" fill="${skin}"/><path d="M35 22q1-22 15-22t15 22q-9-7-30 0" fill="${hair}"/><rect x="${50-wide}" y="48" width="${wide*2}" height="65" rx="14" fill="${color}"/><path d="M38 59L23 110M62 59l15 51" stroke="${skin}" stroke-width="8" stroke-linecap="round"/><path d="M42 110l-6 80M58 110l6 80" stroke="#4d514b" stroke-width="13" stroke-linecap="round"/><path d="M31 194h13M56 194h13" stroke="#222" stroke-width="8" stroke-linecap="round"/><path d="M40 53h20" stroke="rgba(255,255,255,.35)" stroke-width="2"/></svg>`}

function modelThumb(g,c){return `<span class="figure ${g}" style="--look:${c}"><i class="head"></i><i class="torso"></i><i class="leg l"></i><i class="leg r"></i></span>`}
function ensureOwnedColor(id,i){const cur=picked(id);if((i.colorStock?.[cur]||0)>0)return cur;const first=colorways(id).findIndex((_,n)=>(i.colorStock?.[n]||0)>0);if(first>=0)colorChoice[id]=first;return first>=0?first:cur}
function colorStockLine(p,i){return `<div class="color-stock">${colorways(p.id).map((c,n)=>`<span><i style="--dot:${c[1]}"></i>${c[0]} <b>${i.colorStock?.[n]??0}</b></span>`).join("")}</div>`}
function ownColorStockLine(p){const i=V.inventory?.[p.id]||{stock:0,colorStock:{}},parts=colorways(p.id).map((c,n)=>`<span><i style="--dot:${c[1]}"></i>${c[0]} <b>${i.colorStock?.[n]||0}</b></span>`).join("");return `<div class="own-stock-line"><strong>내 재고 ${i.stock||0}</strong><div>${parts}</div></div>`}
function gameDateFor(d){const t=14+Number(d)-1,mi=Math.floor(t/30),y=2027+Math.floor(mi/12),m=mi%12+1,dd=t%30+1;return `${y}.${String(m).padStart(2,"0")}.${String(dd).padStart(2,"0")}`}
const HISTORY_PAGE_SIZE=20;
function historyRecords(type){const h=V.history||{},base=type==="operations"?(h.operations||[]):type==="sales"?(h.sales||[]):h.logistics||[],from=Math.max(1,Number(historyRange.from)||1),to=Math.min(V.day,Number(historyRange.to)||V.day);return base.filter(x=>(x.day||1)>=from&&(x.day||1)<=to).sort((a,b)=>(b.day||0)-(a.day||0))}
function historyDateOptions(selected){let out="";for(let d=1;d<=V.day;d++)out+=`<option value="${d}" ${Number(selected)===d?"selected":""}>${gameDateFor(d)} · D${d}</option>`;return out}
function operationLine(x){let text=x?.text||"운영 기록";if(Array.isArray(x?.items)&&x.items.length){const parts=x.items.map(v=>{const p=product(v.id),c=colorways(v.id)?.[Number(v.color||0)]?.[0]||"Color";return p?`${p.name} · ${c} ×${v.qty||0}`:""}).filter(Boolean);if(parts.length)return `${text} · ${parts.join(" / ")}`}if(x?.id&&x.color!=null){const p=product(x.id),c=colorways(x.id)?.[Number(x.color||0)]?.[0]||"Color";if(p?.name&&text.includes(p.name))return text.replace(p.name,`${p.name} · ${c}`);if(p?.name)return `${p.name} · ${c} · ${text}`}return text}
function scheduledRow(x){const p=product(x.id),c=colorways(x.id)?.[Number(x.color||0)]?.[0]||"Color";return `<div class="log schedule-row"><b class="log-date">${gameDateFor(x.dueDay)}</b><span><strong>${escapeHtml(x.kind)}</strong> · ${escapeHtml(p?.name||x.id)} · ${escapeHtml(c)} · ${x.qty||0}장</span></div>`}
function salesColorBreakdown(x){const entries=Object.entries(x.colorSales||{}).filter(([,q])=>Number(q)>0);if(!entries.length)return `<span class="sales-color-empty">컬러 상세 기록 없음</span>`;const cw=colorways(x.id)||[];return entries.sort((a,b)=>Number(a[0])-Number(b[0])).map(([k,q])=>{const col=cw[Number(k)]||["Color","#bbb"];return `<span class="sales-color-item"><i style="--sale-color:${escapeHtml(col[1]||"#bbb")}"></i><b>${escapeHtml(col[0]||"Color")}</b><em>${Number(q)}장</em></span>`}).join("")}
function historyRow(type,x){if(type==="operations")return `<div class="history-row"><div class="history-main"><b>${x.date||gameDateFor(x.day)}</b><span>${escapeHtml(operationLine(x))}</span></div></div>`;const p=product(x.id),name=p?.name||x.id||"상품",color=colorways(x.id)?.[Number(x.color||0)]?.[0]||"";if(type==="sales")return `<div class="history-row sales-history-row"><div class="history-main"><b>${escapeHtml(name)}</b><span>${x.date||gameDateFor(x.day)} · D${x.day}</span></div><div class="sales-color-breakdown">${salesColorBreakdown(x)}</div><div class="history-values"><b>${x.qty||0}장</b><span>온라인 ${x.online||0} · 오프라인 ${x.offline||0}</span><em>${money(x.revenue||0)}</em></div></div>`;return `<div class="history-row"><div class="history-main"><b>${escapeHtml(x.kind||"입고·반품")} · ${escapeHtml(name)}</b><span>${x.date||gameDateFor(x.day)} · ${escapeHtml(color)}${color?" · ":""}${x.qty||0}장</span></div><div class="history-values"><em>${x.kind==="온라인 반품"?"환불 ":"금액 "}${money(x.amount||0)}</em></div></div>`}
function historyPanel(){if(!historyView)return"";const labels={sales:"판매 전체 기록",logistics:"입고·반품 전체 기록",operations:"운영 전체 기록"},records=historyRecords(historyView),pages=Math.max(1,Math.ceil(records.length/HISTORY_PAGE_SIZE));historyPage=Math.min(Math.max(1,historyPage),pages);const start=(historyPage-1)*HISTORY_PAGE_SIZE,rows=records.slice(start,start+HISTORY_PAGE_SIZE),to=historyRange.to||V.day;return `<div class="card history-panel" id="historyPanel"><div class="history-panel-head"><div><div class="eyebrow">HISTORY</div><h2>${labels[historyView]}</h2></div><button class="history-close" data-history-close="1">닫기 ×</button></div><div class="history-filter"><label><span>시작일</span><select data-history-from="1">${historyDateOptions(historyRange.from||1)}</select></label><label><span>종료일</span><select data-history-to="1">${historyDateOptions(to)}</select></label><div class="history-count">${records.length}건</div></div>${rows.length?`${historyView==="sales"?`<div class="sales-history-head"><span>상품명</span><span>컬러별 판매량</span><span>총 판매량</span></div>`:""}<div class="history-list ${historyView==="sales"?"sales-history-list":""}">${rows.map(x=>historyRow(historyView,x)).join("")}</div>`:`<div class="empty">선택한 기간의 기록이 없습니다.</div>`}<div class="history-pagination"><button class="btn" data-history-page="prev" ${historyPage<=1?"disabled":""}>← 이전</button><span>${historyPage} / ${pages}</span><button class="btn" data-history-page="next" ${historyPage>=pages?"disabled":""}>다음 →</button></div></div>`}
function getModel(id,i){return modelChoice[id]||i.model||"female"}
function apDots(){return `<span class="apdots">${Array.from({length:V.maxAp||5},(_,i)=>`<i class="${i<V.ap?"":"off"}"></i>`).join("")}</span>`}
function sortSelect(scope,items){return `<label class="sort-control"><span>정렬</span><select data-sort="${scope}">${items.map(([v,n])=>`<option value="${v}" ${sortChoice[scope]===v?"selected":""}>${n}</option>`).join("")}</select></label>`}
function supplierSortName(id){const p=product(id);return p?.source==="ORIGINAL"?"ADDER ORIGINAL":supplier(p?.supplierId)?.name||""}
function lastRecent(id,scope){const i=V.inventory?.[id]||{};if(scope==="dash")return i.lastSoldDay||0;if(scope==="inventory")return i.lastStockSeq||((i.lastStockDay||0)*1000000);return V.productActivity?.[id]||V.sampledDay?.[id]||i.lastStockDay||0}
function directionSelect(scope){return `<label class="sort-control"><span>순서</span><select data-sort-dir="${scope}"><option value="desc" ${sortDirection[scope]==="desc"?"selected":""}>내림차순 ↓</option><option value="asc" ${sortDirection[scope]==="asc"?"selected":""}>오름차순 ↑</option></select></label>`}
function brandKey(id){const p=product(id);return p?.source==="ORIGINAL"?"original":p?.supplierId||""}
function filteredIds(ids,scope){const f=filterChoice[scope]||{brand:"all",style:"all"};return ids.filter(id=>{const p=product(id);return(f.brand==="all"||brandKey(id)===f.brand)&&(f.style==="all"||p.trend===f.style)})}
function filterSelect(scope,kind,label,items,current){const opts=items.map(([v,n])=>`<option value="${v}" ${current===v?"selected":""}>${n}</option>`).join("");return `<label class="filter-control"><span>${label}</span><select data-filter-${kind}="${scope}"><option value="all">전체 ${label}</option>${opts}</select></label>`}
function filterToolbar(scope,ids){const ps=ids.map(product).filter(Boolean),brands=[...new Set(ids.map(brandKey))].map(k=>[k,k==="original"?"ADDER ORIGINAL":supplier(k)?.name||k]).sort((a,b)=>a[1].localeCompare(b[1],"ko")),styles=[...new Set(ps.map(p=>p.trend))].map(k=>[k,trendKo[k]||k]).sort((a,b)=>a[1].localeCompare(b[1],"ko"));return `<div class="filter-bar">${filterSelect(scope,"brand","브랜드",brands,filterChoice[scope].brand)}${filterSelect(scope,"style","스타일",styles,filterChoice[scope].style)}</div>`}
function inventoryStockControls(){return `<div class="stock-view-controls"><label><input type="checkbox" data-stock-view="inStock" ${inventoryStockView==="inStock"?"checked":""}><span>품절제품 제외하고 보기</span></label><label><input type="checkbox" data-stock-view="soldOut" ${inventoryStockView==="soldOut"?"checked":""}><span>품절제품만 보기</span></label></div>`}
function reorderStockControls(){return `<div class="stock-view-controls"><label><input type="checkbox" data-reorder-stock-view="inStock" ${reorderStockView==="inStock"?"checked":""}><span>품절제품 제외하고 보기</span></label><label><input type="checkbox" data-reorder-stock-view="soldOut" ${reorderStockView==="soldOut"?"checked":""}><span>품절제품만 보기</span></label></div>`}
function reorderOwnStockControls(){return `<div class="stock-view-controls own-stock-controls"><label><input type="checkbox" data-reorder-own-stock-view="soldOut" ${reorderOwnStockView==="soldOut"?"checked":""}><span>우리가게 품절제품 보기</span></label><label><input type="checkbox" data-reorder-own-stock-view="inStock" ${reorderOwnStockView==="inStock"?"checked":""}><span>우리가게 품절제품 제외하고 보기</span></label></div>`}
function marketHistoryControls(){return `<div class="stock-view-controls"><label><input type="checkbox" data-market-history-view="bought" ${marketHistoryView==="bought"?"checked":""}><span>구매이력상품만 보기</span></label><label><input type="checkbox" data-market-history-view="new" ${marketHistoryView==="new"?"checked":""}><span>구매이력상품 제외하고 보기</span></label></div>`}
function newnessRank(p){return (Number.isInteger(p?.seasonIndex)?p.seasonIndex:-1)*1000+(Number(p?.releaseDay)||0)}
function sortedIds(ids,scope){const mode=sortChoice[scope],dir=sortDirection[scope]||"desc";return [...ids].sort((a,b)=>{const pa=product(a),pb=product(b),ia=V.inventory?.[a]||{},ib=V.inventory?.[b]||{};let av,bv;if(mode==="supplier"){av=supplierSortName(a);bv=supplierSortName(b)}else if(mode==="sold"){av=ia.sold||0;bv=ib.sold||0}else if(mode==="stock"){av=scope==="reorder"?(V.availability?.[a]||0):(ia.stock||0);bv=scope==="reorder"?(V.availability?.[b]||0):(ib.stock||0)}else if(mode==="quality"){av=pa.quality||0;bv=pb.quality||0}else if(mode==="new"){av=newnessRank(pa);bv=newnessRank(pb)}else if(mode==="firstStock"){av=Number(ia.firstStockDay)||0;bv=Number(ib.firstStockDay)||0;if(!av&&bv)return 1;if(av&&!bv)return -1}else if(mode==="price"){if(scope==="market"){av=pa.wholesale||0;bv=pb.wholesale||0}else if(scope==="reorder"){av=Math.round(pa.wholesale*(1-discount(V.suppliers[pa.supplierId]?.relation||0)/100));bv=Math.round(pb.wholesale*(1-discount(V.suppliers[pb.supplierId]?.relation||0)/100))}else{av=ia.price||pa.retail;bv=ib.price||pb.retail}}else{av=lastRecent(a,scope);bv=lastRecent(b,scope)}let cmp=typeof av==="string"?av.localeCompare(bv,"ko"):(av-bv);if(dir==="desc")cmp=-cmp;return cmp||pa.name.localeCompare(pb.name,"ko")})}
function saveManager(){
  const rows=saveSlots.length?saveSlots.map(slot=>`<div class="save-row"><div class="save-row-main"><b>${escapeHtml(slot.name)}</b><span>${gameDateFor(slot.day||1)} · D${slot.day||1} · 현금 ${money(slot.cash||0)} · 누적매출 ${money(slot.revenue||0)}</span></div><div class="save-row-actions"><button class="btn" data-save-load="${slot.id}">불러오기</button><button class="btn save-file-mini" data-save-export="${slot.id}">파일</button><button class="save-delete" data-save-delete="${slot.id}">삭제</button></div></div>`).join(""):`<div class="save-empty">아직 수동 저장이 없습니다.</div>`;
  return `<div class="save-backdrop" data-save-backdrop="1"><section class="save-modal" role="dialog" aria-modal="true" aria-label="게임 저장 관리"><div class="save-head"><div><div class="eyebrow">SAVE MANAGER</div><h2>게임 저장</h2></div><button class="history-close" data-save-close="1">닫기 ×</button></div><div class="save-create"><input id="saveName" maxlength="40" value="SAVE ${saveSlots.length+1}" aria-label="저장 이름"><button id="saveCurrent" class="btn primary">현재 진행 저장</button></div><div class="save-note">수동 저장 최대 12개 · 현재 게임은 평소처럼 자동 유지됩니다.</div><div class="save-file-tools"><div><b>파일 백업</b><span>업데이트 후에도 복원 가능 · V10 iPhone/iPad 서로 호환</span></div><div class="save-file-actions"><button id="exportCurrentSave" class="btn" ${saveImportBusy?"disabled":""}>현재 진행 파일 저장</button><button id="importSaveFile" class="btn primary" ${saveImportBusy?"disabled":""}>${saveImportBusy?"불러오는 중…":"파일 불러오기"}</button><input id="saveFileInput" type="file" accept=".json,application/json" hidden></div></div>${saveImportBusy?`<div class="save-note"><b>${escapeHtml(saveImportStatus||"SAVE 불러오는 중…")}</b> 파일 검증이 끝난 뒤에만 현재 진행상태가 교체됩니다.</div>`:""}<div class="save-note pwa-status" aria-live="polite"></div><div class="save-list">${rows}</div><div class="save-new"><div><b>새 게임</b><span>저장 목록은 남겨두고 현재 진행만 처음부터 시작합니다.</span></div><button id="newGame" class="btn red">새 게임 시작</button></div></section></div>`
}
