function act(b){
  const t=b.dataset.action,id=b.dataset.id;
  if(t==="reportMaliciousReview")send({type:t,caseId:b.dataset.case});
  else if(t==="sponsorInfluencer"){if(!selectedInfluencerId||!sponsorProductId)return toast("인플루언서와 협찬 상품을 선택해주세요.",true);send({type:t,influencerId:selectedInfluencerId,productId:sponsorProductId,color:Number(sponsorColor||0)});}
  else if(t==="marketRefresh"){marketCart={};send({type:t});}
  else if(t==="discoverSupplier")send({type:t});
  else if(t==="marketOrder"){const sid=b.dataset.supplier,items=marketCart[sid]||[];if(!items.length)return toast("이 가게 주문이 비어 있습니다.",true);pendingCartClear={type:"market",supplierId:sid};send({type:t,supplierId:sid,items});}
  else if(t==="reorderOrder"){if(!reorderCart.length)return toast("장바구니가 비어 있습니다.",true);pendingCartClear={type:"reorder"};send({type:t,items:reorderCart});}
  else if(t==="setPrice")send({type:t,id,price:Number($(`#price-${id}`).value)});
  else if(t==="shoot")send({type:t,id,method:b.dataset.method,color:picked(id),model:getModel(id,V.inventory[id])});
  else if(t==="postReel")send({type:t,format:b.dataset.format});
  else if(t==="upgradeSite")send({type:t});
  else if(t==="leaseStore")send({type:t,locationId:b.dataset.location});
  else if(t==="expandStore")send({type:t});
  else if(t==="contractFactory")send({type:t});
  else if(t==="developOriginalProduct")send({type:t,trend:originalDevelopmentStyle});
  else if(t==="addOriginalColor"){const d=originalDraft(id);d.h=Number($(`#oh-${id}`)?.value??d.h);d.s=Number($(`#os-${id}`)?.value??d.s);d.l=Number($(`#ol-${id}`)?.value??d.l);d.name=String($(`#ocn-${id}`)?.value??d.name).trim();if(!d.name)return toast("컬러 이름을 입력해주세요.",true);pendingOriginalColorId=id;send({type:t,id,name:d.name,hue:d.h,saturation:d.s,lightness:d.l});}
  else if(t==="produceOriginal")send({type:t,id,color:picked(id),qty:Number($(`#oq-${id}`).value)});
}
