function addCartLine(list,id,color,qty){
  const q=Math.max(1,Math.min(200,Number(qty)||1));
  const hit=list.find(x=>x.id===id&&x.color===color);
  if(hit)hit.qty=Math.min(200,hit.qty+q);else list.push({id,color,qty:q});
}
